param()
$ErrorActionPreference = "Stop"

Write-Host "========================================================" -ForegroundColor Green
Write-Host " IPPLIAP - PS36B FINALIZAR WORD/EXCEL" -ForegroundColor Green
Write-Host "========================================================" -ForegroundColor Green

Set-Location "C:\Users\Leo\Documents\Prototipo_B"

if ((git branch --show-current).Trim() -ne "main") {
    throw "Debe ejecutar este script en la rama main."
}

$Backup = Join-Path $env:TEMP ("IPPLIAP_PS36B_" + (Get-Date -Format "yyyyMMdd_HHmmss"))
New-Item -ItemType Directory -Path $Backup -Force | Out-Null
Copy-Item ".\app\services\institutional_export_service.py" $Backup -Force
Write-Host "Backup temporal: $Backup" -ForegroundColor Yellow

$PatchFile = Join-Path $env:TEMP "ippliap_ps36b_patch.py"
$PatchBase64 = ""
$PatchBytes = [Convert]::FromBase64String($PatchBase64)
[IO.File]::WriteAllBytes($PatchFile, $PatchBytes)

$env:PYTHONPATH = (Get-Location).Path

python $PatchFile
if ($LASTEXITCODE -ne 0) {
    throw "PS36B no pudo modificar institutional_export_service.py. NO HAGA COMMIT."
}

python -m py_compile `
    ".\app\services\institutional_form_service.py" `
    ".\app\services\institutional_export_service.py"

if ($LASTEXITCODE -ne 0) {
    throw "Error de compilacion. NO HAGA COMMIT."
}

python -c "from app import create_app; a=create_app(); print('APP_OK:', a.name)"
if ($LASTEXITCODE -ne 0) {
    throw "create_app fallo. NO HAGA COMMIT."
}

Remove-Item Env:PYTHONPATH -ErrorAction SilentlyContinue

Write-Host ""
Write-Host "PS36B COMPLETADO CORRECTAMENTE" -ForegroundColor Green
Write-Host "Ahora ejecute: .\37b_validar_responsables_exportacion.ps1" -ForegroundColor Cyan
Write-Host ""
git status --short
